function bindCalc(){
  /* Accepts Arabic-Indic (٠-٩) and Persian (۰-۹) digits and a comma decimal,
     because this is an Arabic-first site and those keypads are normal here.
     Negative values are never meaningful in a landed-cost model. */
  const normNum = v => String(v==null?"":v)
      .replace(/[\u0660-\u0669]/g,c=>c.charCodeAt(0)-0x0660)
      .replace(/[\u06F0-\u06F9]/g,c=>c.charCodeAt(0)-0x06F0)
      .replace(/[\u066B,]/g,".")
      .replace(/[\u066C\u2066-\u2069\s]/g,"");
  const g=k=>{
    const e=document.getElementById("c_"+k); if(!e) return 0;
    const n=parseFloat(normNum(e.value));
    return Number.isFinite(n) && n>0 ? n : 0;
  };
  const el=i=>document.getElementById(i);
  const calc=()=>{
    const unit=g("unit"),qty=g("qty"),frtot=g("frtot"),dutyP=g("duty"),vatP=g("vat"),
          comp=g("comp"),fee=g("fee"),other=g("other"),sell=g("sell");
    const ck=document.getElementById("c_ctry").value, C=CTRY()[ck]||{};
    const goods=unit*qty;
    const cif=goods+frtot;
    const duty=cif*dutyP/100;
    const vat=(cif+duty)*vatP/100;
    let gov=0;
    if(C.gov && cif>0){ const inLocal=cif*C.gov.rate*C.gov.pct;
      gov=Math.min(Math.max(inLocal,C.gov.min),C.gov.max)/C.gov.rate; }
    const svc=fee+other+comp+gov;
    const total=goods+frtot+duty+vat+svc;
    const per= qty>0 ? total/qty : 0;
    const rev=sell*qty, profit=rev-total;
    const margin= sell>0 ? (sell-per)/sell*100 : 0;
    const be= sell>0 ? Math.ceil(total/sell) : 0;

    /* A quantity is required before any per-unit or margin figure means
       anything. Without it, per-unit cost is 0 and margin reads a flattering
       100% — the opposite of the truth on an unfinished form. */
    const ready = qty>0 && unit>0;
    el("o_unit").textContent = ready ? "$"+money(per) : "—";
    el("o_unitsub").textContent = ready
      ? L(`مقابل ${money(unit)} $ سعر المصنع — الزيادة ${Math.round((per/unit-1)*100)}%`,
          `vs $${money(unit)} ex-factory — a ${Math.round((per/unit-1)*100)}% uplift`)
      : L("أدخل سعر الوحدة والكمية أولًا.","Enter the unit price and quantity first.");
    el("o_total").textContent  = ready ? "$"+money(total) : "—";
    el("o_margin").textContent = (ready && sell>0) ? clampPct(margin) : "—";
    el("o_profit").textContent = ready ? "$"+money(profit) : "—";
    el("o_be").textContent     = (ready && sell>0 && total>0)
      ? be.toLocaleString("en-US")+" "+L("وحدة","units") : "—";
    el("o_margin").className   = margin<0 ? "neg" : (margin<20 ? "warn" : "");
    el("o_profit").className   = profit<0 ? "neg" : "";

    const vals={goods,freight:frtot,duty,vat,fee:svc};
    const dark=document.documentElement.getAttribute("data-theme")==="dark";
    let bar="",leg="",tab="";
    CC().forEach(([k,label,cl,cd])=>{
      const v=vals[k], pct= total>0 ? v/total*100 : 0, c= dark?cd:cl;
      if(pct>0.05) bar+=`<span class="seg" style="width:${pct}%;background:${c}" title="${label}: $${money(v)} (${pct.toFixed(1)}%)">${pct>=4?`<i>${pct.toFixed(0)}%</i>`:""}</span>`;
      leg+=`<span class="lg"><i style="background:${c}"></i>${label}</span>`;
      tab+=`<tr><td><i class="sw" style="background:${c}"></i>${label}</td><td>$${money(v)}</td><td>${pct.toFixed(1)}%</td></tr>`;
    });
    el("o_bar").innerHTML=bar; el("o_leg").innerHTML=leg;
    el("o_tab").innerHTML=tab+`<tr class="total"><td>${L("الإجمالي","Total")}</td><td>$${money(total)}</td><td>100%</td></tr>`;
    const sub=[[L("رسوم الخدمة","Service fee"),fee],[L("رسوم المطابقة والشهادات","Conformity & certificates"),comp],
               [L("رسوم الخدمة الجمركية","Customs service fee"),gov],[L("تكاليف أخرى","Other costs"),other]]
      .filter(x=>x[1]>0);
    el("o_sub").innerHTML = sub.length
      ? L("داخل بند الخدمة والامتثال: ","Inside the service & conformity line: ")+
        sub.map(x=>`${x[0]} $${money(x[1])}`).join(" · ")
      : "";

    const msg=L(`حسبة تقديرية من الموقع:\nبلد الوصول: ${C.n||"—"}\nالكمية: ${qty}\nسعر المصنع: ${money(unit)} $\nتكلفة الوحدة النهائية: ${money(per)} $\nرأس المال: ${money(total)} $\nهامش الربح الإجمالي: ${margin.toFixed(1)}%`,
                `Estimate from the site:\nDestination: ${C.n||"—"}\nQty: ${qty}\nEx-factory: $${money(unit)}\nLanded unit cost: $${money(per)}\nCapital: $${money(total)}\nMargin: ${margin.toFixed(1)}%`);
    el("o_send").href = waLink(msg);
    el("o_send").target="_blank"; el("o_send").rel="noopener";
  };
  const sel=document.getElementById("c_ctry");
  const setC=(apply)=>{
    const C=CTRY()[sel.value]||{};
    const note=document.getElementById("c_cnote");
    note.innerHTML = `<b>${C.body||""}</b>${C.note?" — "+C.note:""}`+
      ` <a href="/compliance" style="white-space:nowrap">${L("تفاصيل المطابقة ←","Conformity details →")}</a>`;
    if(apply){
      /* Where a country has no published headline rate (Yemen, "another
         country"), blank the field and ask for a figure. Leaving the previous
         country's numbers in place shows the user someone else's rates as
         though they were their own. */
      [["duty",C.duty],["vat",C.vat],["comp",C.comp]].forEach(([k,v])=>{
        const e=document.getElementById("c_"+k); if(!e) return;
        if(v!=null){ e.value=v; e.removeAttribute("placeholder"); }
        else { e.value=""; e.setAttribute("placeholder",L("أدخل نسبتك","Enter your own rate")); }
      });
    }
    calc();
  };
  sel.addEventListener("change",()=>setC(true));
  document.querySelectorAll(".calc-in input").forEach(i=>i.addEventListener("input",calc));
  const pb=document.getElementById("o_print");
  if(pb) pb.addEventListener("click",()=>window.print());
  setC(false);
}

function bindFaq(){
  const inp=$("#fq"), acc=$("#facc"), empty=$("#fqe"), num=$("#fqn");
  if(!inp) return;
  const items=[...acc.querySelectorAll("details")];
  const norm=t=>t.toLowerCase().replace(/[\u064B-\u065F\u0670]/g,"").replace(/[أإآ]/g,"ا").replace(/ى/g,"ي").replace(/ة/g,"ه");
  const run=()=>{
    const q=norm(inp.value.trim());
    let shown=0;
    items.forEach(d=>{
      const hit = !q || norm(d.textContent).includes(q);
      d.style.display = hit ? "" : "none";
      if(hit) shown++;
      if(q && hit) d.open = true; else if(!q) d.open = false;
    });
    empty.style.display = shown ? "none" : "block";
    acc.style.display   = shown ? "" : "none";
    num.textContent = q ? L(`${shown} نتيجة`,`${shown} result${shown===1?"":"s"}`) : "";
  };
  inp.addEventListener("input",run);
}

const QKEY="rsbl_qf";
function bindQualify(){
  const steps=[...document.querySelectorAll(".fstep")], defs=Q_STEPS();
  let i=0;
  const bar=$("#bar"),st=$("#stitle"),sc=$("#scount"),prev=$("#prev"),next=$("#next"),send=$("#send"),form=$("#qform");
  const draw=()=>{
    steps.forEach((s,x)=>s.classList.toggle("on",x===i));
    bar.style.width=((i+1)/steps.length*100)+"%";
    st.textContent=defs[i].t; sc.textContent=L(`الخطوة ${i+1} من ${steps.length}`,`Step ${i+1} of ${steps.length}`);
    prev.style.display=i?"block":"none"; next.style.display=i<steps.length-1?"block":"none";
    send.style.display=i===steps.length-1?"block":"none";
    window.scrollTo({top:$("#qf").offsetTop-90,behavior:"smooth"});
  };
  const valid=()=>{
    let ok=true, first=null;
    defs[i].f.filter(f=>f.req).forEach(f=>{
      const els=form.querySelectorAll(`[name="${f.k}"]`);
      let has=false, bad=false;
      els.forEach(e=>{
        if(e.type==="radio"||e.type==="checkbox"){ if(e.checked) has=true; }
        else if(e.value.trim()){ has=true; if(!e.checkValidity()) bad=true; }
      });
      const err=form.querySelector(`.err[data-for="${f.k}"]`);
      if(err){
        err.textContent = bad
          ? L("تحقّق من صيغة ما كتبته.","Please check the format of what you entered.")
          : L("هذا الحقل مطلوب.","This field is required.");
        err.classList.toggle("on", !has || bad);
      }
      els.forEach(e=>e.setAttribute("aria-invalid", (!has||bad) ? "true" : "false"));
      if((!has||bad) && !first) first = els[0];
      if(!has||bad) ok=false;
    });
    if(first) first.focus();
    return ok;
  };
  /* Keep what the visitor typed across a language or theme switch, and across
     an accidental navigation. Cleared once the request is actually received. */
  const saveState=()=>{
    try{
      const o={}; new FormData(form).forEach((v,k)=>{ o[k]=o[k]?o[k]+"|"+v:v; });
      store.s(QKEY, JSON.stringify({step:i,data:o}));
    }catch(e){}
  };
  const restoreState=()=>{
    try{
      const raw=store.g(QKEY); if(!raw) return;
      const {step,data}=JSON.parse(raw); if(!data) return;
      Object.entries(data).forEach(([k,v])=>{
        const vals=String(v).split("|");
        form.querySelectorAll(`[name="${k}"]`).forEach(e=>{
          if(e.type==="radio"||e.type==="checkbox") e.checked=vals.includes(e.value);
          else e.value=vals[0];
        });
      });
      if(Number.isInteger(step) && step>=0 && step<steps.length) i=step;
    }catch(e){}
  };
  restoreState();
  form.addEventListener("input",saveState);
  form.addEventListener("change",saveState);
  form.addEventListener("change",e=>{
    const o=e.target.closest(".opt"); if(!o) return;
    if(e.target.type==="radio") o.parentElement.querySelectorAll(".opt").forEach(x=>x.classList.remove("sel"));
    o.classList.toggle("sel",e.target.checked);
  });
  next.addEventListener("click",()=>{ if(valid()){ i++; draw(); }});
  prev.addEventListener("click",()=>{ i--; draw(); });
  form.addEventListener("submit",async e=>{
    e.preventDefault(); if(!valid()) return;
    const fd=new FormData(form), data={};
    for(const [k,v] of fd.entries()){ data[k]=data[k]?data[k]+" | "+v:v; }
    data.lang=LANG; data.page=location.href; data.submittedAt=new Date().toISOString();
    const reset=()=>{ send.disabled=false; send.textContent=L("إرسال الطلب","Submit request"); };
    const fail=(m)=>{ reset(); const b=$("#q_err"); if(b){ b.textContent=m; b.hidden=false; b.focus(); } else alert(m); };
    send.disabled=true; send.textContent=L("جارٍ الإرسال…","Sending…");
    const eb=$("#q_err"); if(eb) eb.hidden=true;

    /* A submission counts as received only when the endpoint confirms it.
       Never navigate to the thank-you page on an unverified hand-off. */
    if(CFG.formEndpoint){
      try{
        const r=await fetch(CFG.formEndpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});
        if(!r.ok) throw new Error("HTTP "+r.status);
        try{ store.s(QKEY,""); }catch(e){}
        go("/thanks");
      }catch(err){
        fail(L("تعذّر إرسال الطلب. تحقّق من اتصالك وأعد المحاولة، أو راسلنا مباشرة وسنكمل معك.",
               "We could not send your request. Check your connection and try again, or message us directly and we will take it from there."));
      }
    }else{
      /* No endpoint configured yet: hand off to WhatsApp and say so honestly.
         We do NOT claim the request was received, because it was not. */
      const w=window.open(waLink(L("طلب تأهيل جديد:\n","New qualification request:\n")+Object.entries(data).map(([k,v])=>`${k}: ${v}`).join("\n")),"_blank");
      reset();
      const b=$("#q_err");
      if(b){
        b.className="notice"; b.hidden=false;
        b.innerHTML = w
          ? L("فتحنا لك واتساب ومعه إجاباتك جاهزة. <b>أرسل الرسالة لتصلنا</b> — لم يُسجَّل طلبك بعد.",
              "We have opened WhatsApp with your answers ready. <b>Send the message so it reaches us</b> — your request has not been recorded yet.")
          : L("منع المتصفح فتح واتساب. افتحه يدويًا وأرسل لنا إجاباتك، أو راسلنا على البريد.",
              "Your browser blocked WhatsApp from opening. Please open it manually and send us your answers, or email us instead.");
        b.focus();
      }
    }
  });
  draw();
}

