/* mirrors NOINDEX in build.py: these must never flip to index,follow after hydration */
const NOINDEX = new Set(["/thanks","/passport"]);

const META404 = () => [["الصفحة غير موجودة — Red Sea Business Launch","Page not found — Red Sea Business Launch"],
                       ["الرابط الذي فتحته غير موجود. تصفّح الصفقات الجاهزة أو حاسبة التكلفة أو تواصل معنا.",
                        "The link you opened does not exist. Browse the ready deals, the cost calculator, or get in touch."]];
function setMeta(base, slug){
  let m = META[base] || (base==="/"||base==="" ? META["/"] : META404());
  let url = "https://"+CFG.domain+(base==="/"?"/":base);
  let indexable = (!!META[base] || base==="/" || base==="") && !NOINDEX.has(base);
  /* every deal is its own page: its own title, description and canonical */
  if(base==="/deal"){
    const d = slug && (window.DEALS||[]).find(x=>x.id===slug);
    if(d){ m = [[d.name[0]+" — Red Sea Business Launch", d.name[1]+" — Red Sea Business Launch"], d.short];
           url = "https://"+CFG.domain+"/deal/"+d.id; }
    else { m = META404(); indexable = false; }
  }
  document.title = A(m[0]);
  const set=(sel,val)=>{const e=document.querySelector(sel); if(e) e.setAttribute("content",val);};
  set('meta[name="description"]',A(m[1]));
  set('meta[property="og:title"]',A(m[0]));
  set('meta[property="og:description"]',A(m[1]));
  set('meta[name="twitter:title"]',A(m[0]));
  set('meta[name="twitter:description"]',A(m[1]));
  /* canonical and og:url were static on every route */
  const c=document.querySelector('link[rel="canonical"]'); if(c) c.href=url;
  set('meta[property="og:url"]',url);
  /* an unknown route must not be indexed as a duplicate of the homepage */
  const rb=document.querySelector('meta[name="robots"]');
  if(rb) rb.setAttribute("content", indexable ? "index,follow" : "noindex,follow");
}

function reveal(){
  const els=document.querySelectorAll(".rv:not(.in)");
  if(!("IntersectionObserver" in window)){els.forEach(e=>e.classList.add("in"));return;}
  const io=new IntersectionObserver((en)=>en.forEach(x=>{if(x.isIntersecting){x.target.classList.add("in");io.unobserve(x.target);}}),{threshold:.12});
  els.forEach(e=>io.observe(e));
}

function render(){
  const raw=location.pathname.replace(/\.html$/,"").replace(/\/+$/,"")||"/";
  const parts=raw.split("/").filter(Boolean);
  const base="/"+(parts[0]||"");
  let body;
  if(base==="/"||base==="")            body=pageHome();
  else if(base==="/deals")             body=pageDeals();
  else if(base==="/deal")              body=pageDeal(parts[1]);
  else if(base==="/packages")          body=pagePackages();
  else if(base==="/calculator")        body=pageCalc();
  else if(base==="/qualify")           body=pageQualify();
  else if(base==="/consultation")      body=pageConsult();
  else if(base==="/about")             body=pageAbout();
  else if(base==="/faq")               body=pageFaq();
  else if(base==="/compliance")        body=pageCompliance();
  else if(base==="/supplier-check")     body=pageVerify();
  else if(base==="/yemen")             body=pageYemen();
  else if(base==="/passport")          body=pagePassport();
  else if(base==="/contact")           body=pageContact();
  else if(base==="/legal")             body=pageLegal();
  else if(base==="/thanks")            body=pageThanks();
  else if(base==="/"||base==="")       body=pageHome();
  else                                 body=page404();

  applyTheme();
  document.documentElement.lang = LANG;
  document.documentElement.dir  = LANG==="ar" ? "rtl" : "ltr";
  $("#app").innerHTML = header() + `<main id="main">${body}</main>` + footer() +
    `<nav class="mbar" aria-label="${L('إجراءات سريعة','Quick actions')}">
       <a class="btn btn-primary btn-sm" href="/qualify">${L("ابدأ الآن","Start now")}</a>
       <a class="btn btn-out btn-sm" href="${waLink()}" target="_blank" rel="noopener">${L("واتساب","WhatsApp")}</a>
     </nav>`;
  setMeta(base==="/deal"?"/deal":(base||"/"), parts[1]);

  $("#lang").addEventListener("click",()=>{ const y=window.scrollY; LANG = LANG==="ar"?"en":"ar"; store.s("rsbl_lang",LANG); render(); window.scrollTo(0,y); });
  $("#theme").addEventListener("click",()=>{
    /* Only the tokens change — a full render() threw away scroll position and
       anything typed into the qualification form. */
    THEME = THEME==="dark"?"light":"dark"; store.s("rsbl_theme",THEME); applyTheme();
    const t=$("#theme"); if(t) t.textContent = THEME==="dark"?"☀":"☾";
  });
  $("#burger").addEventListener("click",()=>$("#nav").classList.toggle("open"));
  if(!window.__prog){
    window.__prog=true;
    const bar=document.getElementById("prog");
    const upd=()=>{const h=document.documentElement.scrollHeight-innerHeight;
      bar.style.transform="scaleX("+(h>0?Math.min(1,scrollY/h):0)+")";};
    addEventListener("scroll",upd,{passive:true}); addEventListener("resize",upd); upd();
    addEventListener("scroll",()=>{
      const h=document.querySelector("header.site");
      if(h) h.classList.toggle("stuck",scrollY>8);
    },{passive:true});
    addEventListener("pointermove",e=>{
      const el=e.target.closest(".navy,.hero"); if(!el) return;
      const r=el.getBoundingClientRect();
      el.style.setProperty("--mx",(e.clientX-r.left)+"px");
      el.style.setProperty("--my",(e.clientY-r.top)+"px");
    },{passive:true});
  }
  document.querySelectorAll("#nav a").forEach(a=>a.addEventListener("click",()=>$("#nav").classList.remove("open")));

  if(base==="/deals")   bindDeals();
  if(base==="/qualify") bindQualify();
  if(base==="/faq")     bindFaq();
  if(base==="/calculator") bindCalc();
  if(base==="/compliance") bindCompliance();
  if(base==="/passport") bindPassport();
  if(base==="/consultation" && CFG.calendly){
    $("#calbox").outerHTML = `<iframe src="${CFG.calendly}" style="width:100%;height:640px;border:0;border-radius:10px" title="Booking calendar"></iframe>`;
  }
  const wa=$("#wa"); if(wa) wa.href=waLink();
  reveal();
  const anchor=(location.hash||"").slice(1);
  if(anchor){ const t=document.getElementById(anchor); if(t) setTimeout(()=>t.scrollIntoView({behavior:"smooth"}),80); }
  else window.scrollTo(0,0);
}

/* Real URLs, client-side. Same-origin internal links are intercepted so
   navigation stays instant, while every link remains a genuine href that a
   crawler can follow and a visitor can copy, bookmark or open in a new tab. */
function go(path,replace){
  const cur=location.pathname+location.search+location.hash;
  if(path===cur) return;
  history[replace?"replaceState":"pushState"]({},"",path);
  render();
}
document.addEventListener("click",e=>{
  if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey) return;
  const a=e.target.closest && e.target.closest("a[href]");
  if(!a||a.target==="_blank"||a.hasAttribute("download")) return;
  const href=a.getAttribute("href");
  if(!href||href.startsWith("#")||/^[a-z]+:/i.test(href)) return;
  const u=new URL(href,location.href);
  if(u.origin!==location.origin) return;
  e.preventDefault();
  go(u.pathname+u.search+u.hash);
});
window.addEventListener("popstate",render);

/* Anything still pointing at the old #/route form — a bookmark, a shared
   WhatsApp link, an old search result — lands on the real path instead of
   the homepage. */
(function(){
  const h=location.hash||"";
  if(h.startsWith("#/")){
    const t=h.slice(1).split("#");
    history.replaceState({},"",t[0]+(t[1]?"#"+t[1]:""));
  }
})();
document.addEventListener("DOMContentLoaded",render);
if(document.readyState!=="loading") render();
